<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/lib/business-reports.php';
require_once dirname(__DIR__,3).'/product-purchases-bootstrap.php';
require_once dirname(__DIR__,3).'/tests/fixtures/product-purchases.php';
use function JenangMcp\{purchaseMetricRegistry,purchaseMetricArguments,purchaseMetricRead};
$checks=0;
function pmCheck(bool $value,string $message):void {global $checks;$checks++;if(!$value)throw new RuntimeException($message);}
function pmReject(callable $call,string $message):void {try{$call();}catch(Throwable){pmCheck(true,$message);return;}throw new RuntimeException($message);}
$now=new DateTimeImmutable('2026-10-21T01:00:00Z');$range=['start_date'=>'2026-09-02','end_date'=>'2026-09-02'];
$pdo=product_purchases_fixture();$canonical=jg_product_purchases_payload($pdo,$range);
pmCheck(purchaseMetricRegistry()['product_purchases']['source']==='sku','Explicit source registry');
pmReject(fn()=>purchaseMetricRead($pdo,'product_purchases',$range,$now),'Transaction required');
pmReject(fn()=>purchaseMetricArguments('product_purchases',['start_date'=>'2026-09-02'],$now),'Paired dates required');
pmReject(fn()=>purchaseMetricArguments('product_purchases',['start_date'=>'2026-02-30','end_date'=>'2026-03-01'],$now),'Invalid calendar rejected');
pmReject(fn()=>purchaseMetricArguments('product_purchases',['start_date'=>'2024-01-01','end_date'=>'2026-09-02'],$now),'Range bounded');
pmReject(fn()=>purchaseMetricArguments('product_purchases',['start_date'=>'2026-10-20','end_date'=>'2026-10-22'],$now),'Future range rejected');
pmReject(fn()=>purchaseMetricArguments('product_purchases',['sku'=>str_repeat('x',33)],$now),'SKU bound');
pmReject(fn()=>purchaseMetricArguments('product_purchases',['sku'=>[]],$now),'Strict argument types');
pmReject(fn()=>purchaseMetricArguments('product_purchases',['refresh'=>true],$now),'No source mutation argument');
$schemaBefore=$pdo->query('SELECT name,sql FROM sqlite_master ORDER BY name')->fetchAll();
$pdo->exec('PRAGMA query_only=ON');$pdo->beginTransaction();$report=purchaseMetricRead($pdo,'product_purchases',$range,$now);
pmCheck($report['values']['totals']===$canonical['totals'],'Exact dashboard totals parity');
pmCheck($report['values']['products']===$canonical['products'],'Exact dashboard product list parity');
pmCheck($report['period']['start_at']==='2026-09-01 17:00:00'&&$report['period']['end_before']==='2026-09-02 17:00:00','Canonical Jakarta inclusive boundaries');
pmCheck($report['values']['totals']['order_count']===3,'Mixed-product orders counted once');
pmCheck($report['values']['totals']['purchase_value']===4070.0,'Saved costs, not current SKU COGS');
pmCheck($report['values']['totals']['ordered_qty']===35,'Canonical confirmed-date and status exclusions');
pmCheck($report['freshness']['upstream_sync_verified']===false&&$report['completeness']['business_reconciliation_verified']===false,'Completeness boundaries retained');
pmCheck($report['freshness']['source_max_updated_at']['purchase_orders']!==null,'Real modification timestamps');
pmCheck($schemaBefore===$pdo->query('SELECT name,sql FROM sqlite_master ORDER BY name')->fetchAll(),'No schema side effects under query_only');
$selected=purchaseMetricRead($pdo,'product_purchases',$range+['sku'=>'010125000101'],$now);
pmCheck($selected['values']['totals']['ordered_qty']===25&&$selected['values']['totals']['purchase_value']===3500.0,'Selected SKU canonical totals');
pmCheck(array_column($selected['values']['orders'],'id')===[3,7,2],'Canonical order detail sort');
$empty=purchaseMetricRead($pdo,'product_purchases',$range+['sku'=>'UNBOUGHT'],$now);
pmCheck($empty['values']['totals']['order_count']===0&&$empty['values']['orders']===[],'Observed unbought product remains verified zero');
$all=purchaseMetricRead($pdo,'product_purchases',[],$now);pmCheck($all['period']['kind']==='all_time','All-time supported explicitly');
$legacy=purchaseMetricRead($pdo,'product_purchases',['start_date'=>'2026-09-01','end_date'=>'2026-09-01','sku'=>'ARCHIVED'],$now);
pmCheck($legacy['values']['totals']['ordered_qty']===2,'Historical SKU and placed-time fallback retained');
pmReject(fn()=>purchaseMetricRead($pdo,'product_purchases',['sku'=>'MISSING'],$now),'Unknown product not zero');
pmCheck($pdo->inTransaction(),'Caller transaction preserved');$pdo->rollBack();$pdo->exec('PRAGMA query_only=OFF');
$pdo->exec("UPDATE purchase_orders SET note='DO_NOT_RETURN' WHERE id=2");$pdo->beginTransaction();
pmCheck(!str_contains(json_encode(purchaseMetricRead($pdo,'product_purchases',$range+['sku'=>'010125000101'],$now)),'DO_NOT_RETURN'),'Notes not projected');$pdo->rollBack();
$pdo->exec('UPDATE purchase_order_items SET purchase_order_id=999 WHERE id=1');$pdo->beginTransaction();pmReject(fn()=>purchaseMetricRead($pdo,'product_purchases',$range,$now),'Orphan purchase lines fail closed');$pdo->rollBack();
$pdo=product_purchases_fixture();$pdo->exec('UPDATE sku_skus SET brand_id=999 WHERE sku=\'UNBOUGHT\'');$pdo->beginTransaction();pmReject(fn()=>purchaseMetricRead($pdo,'product_purchases',$range,$now),'Orphan catalog mappings fail closed');$pdo->rollBack();
$missing=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$missing->beginTransaction();pmReject(fn()=>purchaseMetricRead($missing,'product_purchases',[],$now),'Missing source is not zero');$missing->rollBack();
$pdo=product_purchases_fixture();$q=$pdo->prepare('UPDATE purchase_orders SET tag=? WHERE id=2');$q->execute([str_repeat('x',1100000)]);$pdo->beginTransaction();
pmReject(fn()=>purchaseMetricRead($pdo,'product_purchases',$range+['sku'=>'010125000101'],$now),'Oversized result rejected without truncation');$pdo->rollBack();
echo "Product purchase metrics: $checks checks passed\n";
